                    "INSERT INTO contacts (id, client_id, name, email, role) VALUES (?, ?, ?, ?, ?)",
                    ((Number) ct.get("id")).longValue(),
                    ((Number) ct.get("clientId")).longValue(),
                    ct.get("name"), ct.get("email"), ct.get("role"));
        }
