            jdbc.update(
                    "INSERT INTO notes (id, target_type, target_id, body, created_at)"
                            + " VALUES (?, ?, ?, ?, ?)",
                    ((Number) n.get("id")).longValue(),
                    n.get("targetType"),
                    ((Number) n.get("targetId")).longValue(),
